@prefix cdif: <https://w3id.org/cdif/> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .

[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <https://example.org/rv/systolicBP> ;
            sh:resultMessage "A cdi:RepresentedVariable should carry at least one cdif:uses_Concept naming the concept(s) it expresses." ;
            sh:resultPath cdif:uses_Concept ;
            sh:resultSeverity sh:Info ;
            sh:sourceConstraintComponent sh:MinCountConstraintComponent ;
            sh:sourceShape [ sh:message "A cdi:RepresentedVariable should carry at least one cdif:uses_Concept naming the concept(s) it expresses." ;
                    sh:minCount 1 ;
                    sh:path cdif:uses_Concept ;
                    sh:severity sh:Info ] ] .

